.titlebar {
  --calendar-bar-color-fallback: #1373d9;
  position: relative;
  display: flex;
  align-items: flex-start;
  flex-direction: column;
  overflow: hidden;
  padding: calc(var(--calendar-dialog-title-bar-padding-block) + var(--calendar-dialog-top-bar-height)) var(--calendar-dialog-row-padding-inline)
    var(--calendar-dialog-title-bar-padding-block);
  gap: 4px;

  &::before {
    border-radius: var(--calendar-border-radius) var(--calendar-border-radius) 0 0;
    content: "";
    position: absolute;
    inset-block-start: 0;
    inset-inline: 0;
    block-size: var(--calendar-dialog-top-bar-height);
    background: var(--calendar-bar-color, var(--calendar-bar-color-fallback));
  }

  & .titlebar-row {
    position: relative;
    min-inline-size: 100%;
    display: flex;
    align-items: center;
    gap: calc(3 * var(--space-step));
  }

  & .calendar-name {
    flex: 1;

    &::before {
      content: "";
      background: var(--calendar-bar-color, var(--calendar-bar-color-fallback));
      inline-size: 9px;
      block-size: 9px;
      margin-inline-end: 9px;
      display: inline-block;
      border-radius: 9px;
    }
  }

  & .calendar-dialog-title {
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
    display: -webkit-box;
    flex: 1;
    font-size: 1.3636rem;
    font-weight: 500;
    margin: 0;
    overflow: hidden;
    padding-inline: 0;
    text-overflow: ellipsis;
  }

  & .title-button-container {
    display: inline-flex;
    margin-inline-end: calc(2px - var(--button-padding));
    gap: 1px;
    flex: 0;
  }
